import type { ReactNode } from 'react';

const APOSTROPHE_STYLE = {
  letterSpacing: '0.3em',
  marginRight: '0.05em',
} as const;

export const buildCoverPeriod = (
  prefix: string,
  year: string,
  suffix?: string,
): ReactNode =>
  prefix && year ? (
    <span>
      {prefix}
      <span style={APOSTROPHE_STYLE}>&apos;</span>
      {year}
      {suffix && ` | ${suffix}`}
    </span>
  ) : null;
